function afterCalls(count, done) {
  let left = count;
  if (left <= 0) done();
  return () => {
    if (left <= 0) return;
    left--;
    if (left === 0) done();
  };
}

function series(tasks, done) {
  const results = [];
  function runNext(i) {
    if (i === tasks.length) return done(null, results);
    tasks[i]((err, value) => {
      if (err) return done(err);
      results.push(value);
      runNext(i + 1);
    });
  }
  runNext(0);
}

function parallel(tasks, done) {
  if (tasks.length === 0) return done(null, []);
  const results = new Array(tasks.length);
  let left = tasks.length;
  let finished = false;
  tasks.forEach((task, i) => {
    task((err, value) => {
      if (finished) return;
      if (err) { finished = true; return done(err); }
      results[i] = value;
      if (--left === 0) { finished = true; done(null, results); }
    });
  });
}

