const later = (ms, value, err) => cb => setTimeout(() => cb(err ?? null, value), ms);
const run = (fn, tasks) => new Promise(resolve => fn(tasks, (err, results) => resolve({ err, results })));

test("afterCalls", () => {
  let runs = 0;
  const tick = afterCalls(3, () => runs++);
  tick(); tick();
  checkEq(runs, 0);
  tick();
  checkEq(runs, 1);
  tick();
  checkEq(runs, 1);
  let zero = 0;
  afterCalls(0, () => zero++);
  checkEq(zero, 1);
});

test("series runs in order, one at a time", async () => {
  let active = 0, peak = 0;
  const tracked = (ms, v) => cb => { active++; peak = Math.max(peak, active); setTimeout(() => { active--; cb(null, v); }, ms); };
  const { err, results } = await run(series, [tracked(20, "a"), tracked(5, "b"), tracked(10, "c")]);
  checkEq(err, null);
  checkEq(results, ["a", "b", "c"]);
  checkEq(peak, 1);
});

test("series stops at the first error", async () => {
  let started = 0;
  const counted = task => cb => { started++; task(cb); };
  const { err } = await run(series, [counted(later(5, 1)), counted(later(5, null, new Error("boom"))), counted(later(5, 3))]);
  checkEq(err.message, "boom");
  checkEq(started, 2);
});

test("parallel keeps task order", async () => {
  const t = Date.now();
  const { err, results } = await run(parallel, [later(30, "slow"), later(5, "fast"), later(15, "mid")]);
  checkEq(err, null);
  checkEq(results, ["slow", "fast", "mid"]);
  check(Date.now() - t < 60, "tasks should run at the same time");
});

test("parallel reports one error once", async () => {
  let calls = 0;
  await new Promise(resolve => {
    parallel([later(5, null, new Error("first")), later(10, null, new Error("second")), later(15, "ok")], (err) => {
      calls++;
      checkEq(err.message, "first");
    });
    setTimeout(resolve, 40);
  });
  checkEq(calls, 1);
});

test("empty lists", async () => {
  checkEq((await run(series, [])).results, []);
  checkEq((await run(parallel, [])).results, []);
});

